function stOpen(id){const s=SID(id);const o=OPS.filter(x=>x.st===id);openM(esc(s.n),esc(s.city)+(s.fr?' · франшиза':' · своя станция'),`<div class="kv"><span>Машин сегодня</span><b>${s.cars} из ${s.cap}</b></div><div class="kv"><span>Загрузка</span><b>${s.load}%</b></div><div class="kv"><span>Выручка сегодня</span><b>${tg(s.rev)}</b></div><div class="kv"><span>Не прошли ТО</span><b>${Math.round(s.cars*.09)}</b></div><div class="kv"><span>Доп. услуги</span><b>${Math.round(s.cars*.21)}</b></div><div class="kv"><span>Начальник</span><b>${esc(s.head)}</b></div><div class="kv"><span>Операторы на смене</span><b>${o.length?o.map(x=>esc(x.n)+(x.on==='—'?' (нет)':' '+x.on)).join(', '):'2 · отметки в 08:50'}</b></div><div class="kv"><span>Открытые задачи</span><b>${TASKS.filter(t=>t.stn===id&&t.st!=='done').length}</b></div><div class="btns l"><button class="bt p" onclick="closeM();go('booking')">Расписание</button><button class="bt" onclick="closeM();go('tasks')">Задачи станции</button></div>`)}
/* ===== Запись ===== */
const SLOTS=['09:00','09:20','09:40','10:00','10:20','10:40','11:00','11:20','11:40','12:00','14:00','14:20','14:40','15:00','15:20','15:40','16:00','16:20','16:40','17:00'];
let BK={'09:00':'777 ABC 01','09:40':'512 KMR 01','10:00':'341 EMR 09','10:20':'905 BER 01','11:00':'Газель · 018 ALG 01','12:00':'119 DKM 01','14:20':'088 NUR 01','15:00':'302 SAL 01','16:00':'611 ZHN 01','17:00':'777 ABC 01'},bkSt='A1';
SC.booking=()=>`<div class="hd"><div><h2>Запись на техосмотр</h2><p>Свободные окна каждой станции видят колл-центр, бот и сайт. Нажмите свободное окно — запишем клиента, ему уйдёт WhatsApp с адресом.</p></div><div class="btns"><select class="sel" onchange="bkSt=this.value;render()">${ST.slice(0,8).map(s=>`<option value="${s.id}" ${s.id===bkSt?'selected':''}>${esc(s.n)}</option>`).join('')}</select></div></div>
 <div class="g21"><div class="pan"><h3>${esc(SID(bkSt).n)} · ${TODAY} · линия 1</h3><div class="slotg">${SLOTS.map(t=>BK[t]?`<div class="slot busy"><code>${t}</code><b>${esc(BK[t])}</b></div>`:`<div class="slot" onclick="BK['${t}']='новая запись';render();toast('Записано на <b>${t}</b>. Клиенту ушёл WhatsApp с адресом и напоминание за 2 часа.')"><code>${t}</code><span>свободно</span></div>`).join('')}</div></div>
 <div><div class="pan"><h3>Сегодня по станции</h3><div class="kv"><span>Записано</span><b>${Object.keys(BK).length} из ${SLOTS.length}</b></div><div class="kv"><span>Живая очередь</span><b>14</b></div><div class="kv"><span>Не пришли по записи</span><b>2</b></div><div class="kv"><span>Повторный осмотр</span><b>5</b></div></div>
 ${said('«Ваш техосмотр подходит к концу, можем записать. Сегодня есть свободное время в пять — вам удобно в пять или в восемь?»','Бот и менеджер предлагают реальные свободные окна станции.','Из встречи')}</div></div>`;
/* ===== Напоминания ===== */
SC.remind=()=>`<div class="hd"><div><h2>Напоминания об окончании ТО</h2><p>Система знает дату окончания техосмотра каждой машины. За 14 дней — звонок бота, кто не ответил — WhatsApp, кто не записался — задача менеджеру.</p></div><div class="btns"><button class="bt p" onclick="toast('Запущен обзвон 132 клиентов с окончанием ТО до 25.11. Результаты появятся в таблице.')">Запустить обзвон</button></div></div>
 <div class="flow4"><div><b>1</b> За 14 дней — звонок бота: «ТО заканчивается, записать?»</div><div><b>2</b> Не ответил — WhatsApp с кнопками свободных окон</div><div><b>3</b> Не записался за 3 дня — задача менеджеру</div><div><b>4</b> Записался — напоминание за 2 часа и адрес</div></div>
 <div class="strip" style="margin-top:12px"><div><small>ТО кончается в ноябре</small><b>412</b><span>клиентов в базе</span></div><div><small>Бот дозвонился</small><b>280</b><span>68%</span></div><div><small>Записались</small><b class="ok">96</b><span>34% от дозвона</span></div><div><small>У менеджеров</small><b>38</b><span>перезвонить сегодня</span></div><div><small>Повторные визиты</small><b>61%</b><span>клиентов возвращаются</span></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Клиент</th><th>Машина</th><th>ТО до</th><th>Статус</th><th>Запись</th><th></th></tr></thead><tbody>${CLI.map((c,i)=>`<tr><td><b>${esc(c.n)}</b><br><small>${c.ph}</small></td><td>${esc(c.car)}</td><td>${c.end}</td><td>${tag(c.st,c.st.includes('подтвердил')?'g':c.st.includes('не ответил')||c.st.includes('перезвонить')?'w':'i')}</td><td>${c.slot||'—'}</td><td>${c.slot?'':`<button class="bt sm" onclick="event.stopPropagation();CLI[${i}].st='менеджер: записал';CLI[${i}].slot='Сарыарка, 11.11 15:20';render();toast('Записали, клиенту ушёл WhatsApp.')">Записать</button>`}</td></tr>`).join('')}</tbody></table></div>`;
/* ===== Колл-центр ===== */
const CALLS=[['16:38','+7 701 *** 44 12','входящий','Запись на ТО, Камри','Асем','записан'],['16:31','+7 705 *** 90 01','входящий','Цена газосмотра','Асем','ответили'],['16:22','+7 777 *** 18 66','пропущен','—','—','перезвонить'],['16:10','+7 702 *** 51 30','входящий','Не прошёл ТО, тормоза','Ерлан','повторный записан'],['15:58','+7 747 *** 08 73','исходящий','Напоминание ТО','бот','записан'],['03:14','+7 708 *** 22 41','пропущен (ночь)','—','—','перезвонили 09:05'],['02:47','+7 701 *** 70 55','входящий (ночь)','Где ближайшая станция','Бекжан','ответили']];
SC.callc=()=>`<div class="hd"><div><h2>Колл-центр 24/7</h2><p>Все звонки и WhatsApp — в одной ленте: кто звонил, кто ответил, чем закончилось. Пропущенный — сразу задача на перезвон с таймером.</p></div><div class="btns"><span class="live"><i></i>на линии 4 оператора</span></div></div>
 <div class="strip"><div><small>Сегодня звонков</small><b>1 382</b><span>входящих 1 106</span></div><div><small>Пропущено</small><b class="bad">26</b><span>перезвонили 22</span></div><div><small>Среднее ожидание</small><b>0:19</b><span>норма до 0:30</span></div><div><small>Записали на ТО</small><b class="ok">418</b><span>30% звонков</span></div><div><small>Ночная смена</small><b>63</b><span>звонка с 21:00 до 08:00</span></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Время</th><th>Номер</th><th>Тип</th><th>Тема</th><th>Оператор</th><th>Итог</th></tr></thead><tbody>${CALLS.map(c=>`<tr onclick="toast('Запись разговора и карточка клиента откроются здесь.')"><td>${c[0]}</td><td>${c[1]}</td><td>${tag(c[2],c[2].startsWith('пропущен')?'r':c[2]==='исходящий'?'i':'g')}</td><td>${c[3]}</td><td>${c[4]}</td><td>${c[5]}</td></tr>`).join('')}</tbody></table></div>
 ${said('«В основном не исходящие, а входящих много».','Входящие из телефонии и WhatsApp попадают в одну ленту колл-центра.','Индира')}`;
/* ===== Звонобот ===== */
SC.bot=()=>`<div class="hd"><div><h2>Звонобот: расходы и лиды</h2><p>Два касания: бот фильтрует, менеджер дожимает. Видно, сколько стоит каждый лид и запись — и можно сравнить с собственным ботом в портале.</p></div></div>
 <div class="strip"><div><small>Расход в октябре</small><b>${tg(58000)}</b><span>подписка подрядчика</span></div><div><small>Дозвонов</small><b>1 240</b><span>из 2 900 номеров</span></div><div><small>Лидов менеджерам</small><b>312</b><span>25% дозвона</span></div><div><small>Записались</small><b class="ok">141</b><span>45% лидов</span></div><div><small>Цена записи</small><b>411 ₸</b><span>Instagram — 851 ₸</span></div></div>
 <div class="g2"><div class="pan"><h3>Воронка бота · октябрь</h3>${[['Номеров в обзвоне',2900,100],['Дозвонились',1240,43],['Интерес — передан менеджеру',312,11],['Записались на ТО',141,5],['Пришли на станцию',122,4]].map(r=>`<div class="fr"><span>${r[0]}</span>${bar(r[2]*1.0,'g')}<b>${fmt(r[1])}</b></div>`).join('')}</div>
 <div class="pan"><h3>Свой бот в портале — посчитаем</h3><div class="kv"><span>Сейчас подписка</span><b>${tg(58000)} / мес</b></div><div class="kv"><span>Свой бот: телефония + синтез речи</span><b>≈ ${tg(25000)} / мес</b></div><div class="kv"><span>Решение</span><b>после замера 1 месяца</b></div><p class="muted" style="font-size:11px;margin-top:8px">Пока ничего не ломаем: текущий бот передаёт лиды в портал, считаем экономику и только потом решаем.</p></div></div>
 ${said('«Звонобот — мы сейчас платим. Можно, если она сама работает, зачем бот?»','Сначала подключаем текущий бот и замеряем, потом решаем — свой или их.','Маргулан')}`;
/* ===== Воронка ===== */
const DEALS=[['new','ТОО «Астана Логистик»','12 грузовых, ТО под ключ','Ерлан',540000],['new','ИП Сагындык','такси-парк, 30 машин','Асем',1200000],['offer','ТОО «КазСтройТранс»','газосмотр, 8 машин','Ерлан',320000],['offer','Автошкола «Драйв»','14 учебных машин','Асем',420000],['deal','ТОО «Нур Агро»','техника, выезд','Ерлан',760000],['won','Такси «Сапар»','договор на год','Асем',2100000]];
const DS=[['new','Новые'],['offer','КП отправлено'],['deal','Договор'],['won','Заключено']];
SC.funnel=()=>`<div class="hd"><div><h2>Воронка продаж · корпоративные клиенты</h2><p>Таксопарки, автошколы, логистика — договоры на год. Частные клиенты идут через запись и напоминания. Этапы настраиваем под ваш отдел продаж.</p></div><div class="btns"><button class="bt p" onclick="DEALS.unshift(['new','Новый клиент','из звонка','Асем',0]);render()">+ Сделка</button></div></div>
 <div class="kanban k4">${DS.map(([k,n])=>`<div class="kcol"><div class="kh"><b>${n}</b><span>${DEALS.filter(d=>d[0]===k).length}</span></div>${DEALS.map((d,i)=>d[0]===k?`<div class="kc" onclick="const i=DS.findIndex(x=>x[0]===DEALS[${i}][0]);if(i<3){DEALS[${i}][0]=DS[i+1][0];render();toast('Сделка передвинута: <b>'+DS[i+1][1]+'</b>')}"><code>${esc(d[3])}</code><b>${esc(d[1])}</b><span>${esc(d[2])}</span><em>${d[4]?tg(d[4]):'—'}</em></div>`:'').join('')}</div>`).join('')}</div>
 <p class="muted" style="font-size:11px">Нажмите карточку — сделка перейдёт на следующий этап.</p>`;
/* ===== Смены ===== */
SC.shifts=()=>`<div class="hd"><div><h2>Смены операторов</h2><p>Вместо Clockster: оператор нажимает «На смене» с телефона на станции (по геометке), опоздание и невыход видны сразу. График смен — по станциям.</p></div><div class="btns"><button class="bt" onclick="toast('График на декабрь собран по шаблону. Проверьте и опубликуйте.')">График на декабрь</button></div></div>
 <div class="strip"><div><small>Должны выйти</small><b>48</b><span>операторов сегодня</span></div><div><small>Вышли</small><b class="ok">46</b><span>по геометке станции</span></div><div><small>Опоздали</small><b>4</b><span>больше 10 минут</span></div><div><small>Не вышли</small><b class="bad">2</b><span>начальникам ушло уведомление</span></div><div><small>Подмены</small><b>1</b><span>Нура → Промзона</span></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Оператор</th><th>Станция</th><th>Смена</th><th>Отметка</th><th>Статус</th><th></th></tr></thead><tbody>${OPS.map((o,i)=>`<tr><td><b>${esc(o.n)}</b></td><td>${esc(SID(o.st).n)}</td><td>09:00–21:00</td><td>${o.on}</td><td>${o.on==='—'?tag('не вышел','r'):o.on>'09:05'?tag('опоздал','w'):tag('на смене','g')}</td><td>${o.on==='—'?`<button class="bt sm" onclick="event.stopPropagation();OPS[${i}].on='${NOW}';render();toast('Отметка проставлена, начальник станции видит.')">Отметить</button>`:''}</td></tr>`).join('')}</tbody></table></div>
 ${said('«Кто на смену вышел — клик нажимает. Вплоть до материальной ответственности».','Отметка, опоздание и материальная ответственность смены — в карточке оператора.','Индира')}`;
/* ===== KPI ===== */
SC.kpi=()=>{const R=OPS.slice().sort((a,b)=>b.cars+b.extra*2-(a.cars+a.extra*2));
 return `<div class="hd"><div><h2>KPI и рейтинг операторов</h2><p>Машин за смену, продажи доп. услуг, опоздания и оценка клиентов. Рейтинг пересчитывается каждый день и виден самому оператору.</p></div><div class="btns"><div class="seg"><a class="on">Неделя</a><a onclick="toast('Месяц: те же метрики за ноябрь.')">Месяц</a></div></div></div>
 <div class="tw"><table class="t"><thead><tr><th>#</th><th>Оператор</th><th>Станция</th><th class="r">Машин в день</th><th class="r">Доп. услуги</th><th class="r">Оценка</th><th class="r">Опоздания</th><th style="width:18%">Баллы</th></tr></thead><tbody>${R.map((o,i)=>{const sc=o.cars+o.extra*2-o.late*3;return `<tr><td><b>${i+1}</b></td><td><b>${esc(o.n)}</b></td><td>${esc(SID(o.st).n)}</td><td class="r">${o.cars}</td><td class="r">${o.extra}</td><td class="r">${o.rate.toFixed(1)}</td><td class="r ${o.late>2?'bad':''}">${o.late}</td><td>${bar(sc,i<3?'g':i>7?'r':'')}</td></tr>`}).join('')}</tbody></table></div>
 ${said('«Количество машин, сколько каждый провёл. Статистика и рейтинг каждого оператора».','','Индира')}`};
/* ===== Мотивация ===== */
SC.pay=()=>`<div class="hd"><div><h2>Мотивация и зарплата · ноябрь</h2><p>Оклад + за машину + процент с доп. услуг (диагностика, аккумулятор, жидкости) − удержания по материальной ответственности. Оператор видит свой расчёт в телефоне.</p></div><div class="btns"><button class="bt" onclick="toast('Ведомость выгружена в Excel для бухгалтерии.')">Ведомость Excel</button></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Оператор</th><th class="r">Оклад</th><th class="r">За машины</th><th class="r">Доп. услуги</th><th class="r">Удержания</th><th class="r">Итого</th></tr></thead><tbody>${OPS.map(o=>{const a=180000,b=o.cars*22*120,c=o.extra*22*350,d=o.late*3000,t=a+b+c-d;return `<tr><td><b>${esc(o.n)}</b><br><small>${esc(SID(o.st).n)}</small></td><td class="r">${fmt(a)}</td><td class="r">${fmt(b)}</td><td class="r">${fmt(c)}</td><td class="r ${d?'bad':''}">${d?'−'+fmt(d):'—'}</td><td class="r"><b>${tg(t)}</b></td></tr>`}).join('')}</tbody></table></div>
 <div class="g2" style="margin-top:12px"><div class="pan"><h3>Правила (меняются без программиста)</h3><div class="kv"><span>За машину</span><b>120 ₸</b></div><div class="kv"><span>Доп. услуга</span><b>350 ₸</b></div><div class="kv"><span>Опоздание</span><b>−3 000 ₸</b></div><div class="kv"><span>Порог бонуса доп. услуг</span><b>от 2 пакетов в день</b></div></div>
 ${said('«Мотивации продажи от двух пакетов».','Порог и ставки настраиваются в портале.','Индира')}</div>`;
/* ===== Задачник ===== */
SC.tasks=()=>`<div class="hd"><div><h2>Задачник вместо Trello</h2><p>Задачи по отделам и станциям. Просроченные ассистент сам напоминает исполнителю и показывает руководителю — ничего не теряется в переписках.</p></div><div class="btns"><button class="bt" onclick="go('ai')">Поставить голосом</button><button class="bt p" onclick="TASKS.unshift({id:'Т-'+(414+TASKS.length),t:'Новая задача',st:'new',dep:'Технический',who:'Тимур',due:'12.11',from:'вручную',stn:''});render()">+ Задача</button></div></div>
 <div class="kanban k4">${TS.map(([k,n])=>`<div class="kcol" ondragover="event.preventDefault()" ondrop="const t=TASKS.find(x=>x.id===event.dataTransfer.getData('t'));t.st='${k}';render()"><div class="kh"><b>${n}</b><span>${TASKS.filter(t=>t.st===k).length}</span></div>${TASKS.filter(t=>t.st===k).map(t=>`<div class="kc ${t.st==='late'?'kl':''}" draggable="true" ondragstart="event.dataTransfer.setData('t','${t.id}')" onclick="tkNext('${t.id}')"><code>${t.id} · до ${t.due} · ${esc(t.dep)}</code><b>${esc(t.t)}</b><span>${esc(t.who)}${t.stn?' · '+esc(SID(t.stn).n):''} · от: ${esc(t.from)}</span>${t.st==='late'?'<em class="bad">ассистент напомнил</em>':''}</div>`).join('')}</div>`).join('')}</div>
 <p style="font-size:11px;color:var(--muted)">Нажмите карточку — задача перейдёт дальше. Можно перетаскивать.</p>
 ${said('«Даже Trello эта система не работает: кто-то говорит неудобно, кто-то забыл. Агент об этом должен уведомлять».','','Индира')}`;
function tkNext(id){const t=TASKS.find(x=>x.id===id);t.st=t.st==='new'?'work':t.st==='done'?'done':'done';render();toast('Задача <b>'+id+'</b>: '+(t.st==='work'?'в работе':'готово'))}
/* ===== Телефон оператора ===== */
let opOn=false,opCars=17;
SC.op=()=>`<div class="hd"><div><h2>Телефон оператора</h2><p>Всё, что нужно на станции: отметка смены, машины, задачи, свой рейтинг и расчёт зарплаты, база знаний.</p></div></div>
 <div class="phw"><div class="phone3"><div class="phs"><div class="phtop"><b>Арман · Байконур</b><span>${TODAY}</span></div>
  ${opOn?`<div class="opok">На смене с 08:52 · геометка станции</div>`:`<button class="bt p full" onclick="opOn=true;render();toast('Отметка: на смене 08:52, по геометке.')">Я на смене</button>`}
  <div class="kv"><span>Машин сегодня</span><b>${opCars}</b></div><div class="kv"><span>Доп. услуги</span><b>4</b></div><div class="kv"><span>Место в рейтинге</span><b>1 из 46</b></div><div class="kv"><span>Заработано в ноябре</span><b>${tg(286400)}</b></div>
  <button class="bt full" onclick="opCars++;render()">+ Машина прошла ТО</button>
  <h4 style="margin:12px 0 6px;font-size:12px">Мои задачи</h4>${TASKS.filter(t=>t.stn==='A3'&&t.st!=='done').map(t=>`<div class="kv"><span>${esc(t.t)}</span>${tag('до '+t.due,'w')}</div>`).join('')||'<div class="kv"><span>Нет задач</span></div>'}
  <button class="bt full" onclick="go('kb')">База знаний</button><button class="bt full" onclick="go('vac')">Мои отпускные</button>
 </div></div>
 <div><div class="pan"><h3>Почему не приложение из стора</h3><p style="font-size:11.6px;line-height:1.6">Это веб-приложение: открывается по ссылке, ставится ярлыком на экран, присылает уведомления. Обновления — сразу у всех, без App Store.</p></div>
 ${said('«Приложение будет веб-версии? Через телефон открывается, через комп, по ссылке, в любой момент».','Да, одна система для телефона и компьютера.','Индира')}</div></div>`;
/* ===== HR ===== */
const CAND=[['Динара Сулейменова','Оператор ТО','Астана','hh.ru','новый',4],['Ерасыл Махмет','Оператор ТО','Шымкент','hh.ru','звонок','3'],['Алина Брик','Оператор колл-центра (ночь)','Астана','Instagram','собеседование',5],['Мейрам Тлеу','Оператор ТО','Шымкент','hh.ru','тест',4],['Карина Ли','Маркетолог','Астана','hh.ru','новый',3],['Тимофей Ан','Техник-электрик','Караганда','сайт','оффер',5]];
const CS=['новый','звонок','собеседование','тест','оффер'];
SC.hr=()=>`<div class="hd"><div><h2>Вакансии и отклики</h2><p>Отклики с hh.ru приходят сразу в портал: резюме, автоматическая анкета, этапы найма. HR видит воронку по каждой вакансии.</p></div><div class="btns"><button class="bt p" onclick="CAND.unshift(['Новый кандидат','Оператор ТО','Астана','hh.ru','новый',3]);render();toast('Новый отклик с hh.ru')">Симулировать отклик</button></div></div>
 <div class="strip"><div><small>Открытых вакансий</small><b>5</b><span>операторы, колл-центр, маркетолог</span></div><div><small>Откликов за неделю</small><b>64</b><span>hh.ru 51</span></div><div><small>На собеседовании</small><b>9</b><span></span></div><div><small>Вышли на работу</small><b class="ok">3</b><span>за ноябрь</span></div><div><small>Срок закрытия</small><b>11 дн.</b><span>в среднем</span></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Кандидат</th><th>Вакансия</th><th>Город</th><th>Источник</th><th>Этап</th><th>Оценка</th><th></th></tr></thead><tbody>${CAND.map((c,i)=>`<tr><td><b>${esc(c[0])}</b></td><td>${esc(c[1])}</td><td>${esc(c[2])}</td><td>${tag(c[3],c[3]==='hh.ru'?'i':'')}</td><td>${tag(c[4],c[4]==='оффер'?'g':'b')}</td><td>${'★'.repeat(+c[5])}</td><td>${c[4]!=='оффер'?`<button class="bt sm" onclick="event.stopPropagation();CAND[${i}][4]=CS[CS.indexOf(CAND[${i}][4])+1];render()">Дальше</button>`:''}</td></tr>`).join('')}</tbody></table></div>
 ${said('«Чтобы отклики, хедхантеры — обрабатывала и готовые резюме нам скидывала».','','Маргулан')}`;
/* ===== База знаний ===== */
let KB=[['Регламент техосмотра легкового авто','видео 12 мин + тест',1],['Проверка газового оборудования (газосмотр)','видео 18 мин + тест',1],['Как предложить доп. услугу клиенту','скрипт + тест',0],['Прицеп: можно ли проводить ТО','статья',0],['Касса и возвраты','видео 7 мин',0],['Материальная ответственность смены','документ + подпись ЭЦП',0]];
SC.kb=()=>{const done=KB.filter(k=>k[2]).length;return `<div class="hd"><div><h2>Онбординг и база знаний</h2><p>Новый сотрудник проходит уроки и тесты, ставит отметку «прошёл». Через полгода не надо звонить директору — ответ находится поиском.</p></div><div class="btns"><input class="sel" placeholder="Поиск: прицеп, газ, касса" onkeydown="if(event.key==='Enter')toast('Найдено: «Прицеп: можно ли проводить ТО» — открыть статью.')"></div></div>
 <div class="g21"><div class="pan"><h3>Программа «Оператор ТО» · Арман Сейтов</h3>${bar(pct(done,KB.length),'g')}<p style="font-size:11px;margin:6px 0 10px;color:var(--muted)">Пройдено ${done} из ${KB.length}</p>${KB.map((k,i)=>`<div class="li ${k[2]?'':'no'}"><i>${k[2]?'✓':i+1}</i><span><b>${esc(k[0])}</b><br><small>${k[1]}</small></span>${k[2]?tag('прошёл','g'):`<button class="bt sm" onclick="KB[${i}][2]=1;render();toast('Урок пройден, тест 9/10.')">Пройти</button>`}</div>`).join('')}</div>
 <div>${said('«Новенький пришёл — онбординг. Через полгода всё забыл. Он заходит, находит свой вопрос и учится. Машина приехала с прицепом — проводить или нельзя?»','База знаний с видео, тестами и поиском.','Индира')}</div></div>`};
/* ===== Отпускные и досье ===== */
let vDays=14;
SC.vac=()=>{const avg=312000,day=avg/29.3,sum=Math.round(day*vDays);return `<div class="hd"><div><h2>Калькулятор отпускных и досье</h2><p>Сотрудник сам считает примерные отпускные и видит своё досье: дата приёма, стаж, отпуск, документы. Доступ — только к своему.</p></div></div>
 <div class="g2"><div class="pan"><h3>Отпускные · Арман Сейтов</h3><div class="kv"><span>Средняя з/п за 12 мес.</span><b>${tg(avg)}</b></div><div class="kv"><span>Дней отпуска</span><b><span class="stepr"><button onclick="vDays=Math.max(1,vDays-1);render()">−</button><span>${vDays}</span><button onclick="vDays=Math.min(24,vDays+1);render()">+</button></span></b></div><div class="kv"><span>Среднедневной</span><b>${tg(day)}</b></div><div class="kv tot"><span>Примерно к выплате</span><b>${tg(sum*0.9)}</b></div><p style="font-size:10.6px;color:var(--muted)">После ИПН и ОПВ. Точную сумму утверждает бухгалтер.</p></div>
 <div class="pan"><h3>Досье</h3><div class="kv"><span>Принят</span><b>14.03.2024</b></div><div class="kv"><span>Стаж</span><b>2 г. 8 мес.</b></div><div class="kv"><span>Отпуск остаток</span><b>17 дней</b></div><div class="kv"><span>Станция</span><b>Байконур</b></div><div class="kv"><span>Обучение</span><b>2 из 6 уроков</b></div><div class="kv"><span>Документы</span><b>5 подписаны ЭЦП</b></div></div></div>`};
/* ===== Документы и ЭЦП ===== */
let DOCS=[['Трудовой договор','Динара Сулейменова','на подписи'],['Договор о материальной ответственности','Динара Сулейменова','на подписи'],['Приказ о приёме','Динара Сулейменова','подписан'],['Заявление на отпуск','Арман Сейтов','подписан'],['Обходной лист при увольнении','Нурсултан Бекжан','на подписи']];
SC.docs=()=>`<div class="hd"><div><h2>Документы и ЭЦП</h2><p>Приём, отпуск, увольнение — документы по шаблонам, подпись ЭЦП с телефона. При увольнении не остаётся вопросов: всё подписано и хранится в досье.</p></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Документ</th><th>Сотрудник</th><th>Статус</th><th></th></tr></thead><tbody>${DOCS.map((d,i)=>`<tr><td><b>${esc(d[0])}</b></td><td>${esc(d[1])}</td><td>${tag(d[2],d[2]==='подписан'?'g':'w')}</td><td>${d[2]!=='подписан'?`<button class="bt sm" onclick="event.stopPropagation();DOCS[${i}][2]='подписан';render();toast('Подписано ЭЦП, документ в досье.')">Подписать ЭЦП</button>`:''}</td></tr>`).join('')}</tbody></table></div>
 ${said('«Через ЭЦП-ключ подписать настолько все документы, что вообще вопросов не остаётся у этого человека при увольнении».','','Индира')}`;
/* ===== Финансы ===== */
let finT='pl';
SC.fin=()=>{const PL=[['Выручка: техосмотр',38400000],['Выручка: доп. услуги',6100000],['Выручка: газосмотр',2900000],['Роялти франшизы',2480000],['ФОТ',-17800000],['Аренда станций',-6200000],['Маркетинг и звонобот',-1650000],['Оборудование и поверка',-2100000],['Налоги',-3900000],['Прочее',-1400000]];const tot=PL.reduce((a,r)=>a+r[1],0);
 const DDS=[['Остаток на 01.10',14200000],['Поступления от клиентов',47100000],['Роялти',2310000],['Выплаты персоналу',-17600000],['Аренда',-6200000],['Поставщики',-4100000],['Налоги',-3900000],['Остаток на 31.10',31810000]];
 const BAL=[['Деньги',31810000],['Оборудование',86400000],['Дебиторка франчайзи',3120000],['Итого активы',121330000],['Кредиторка',4800000],['Капитал',116530000]];
 const T=finT==='pl'?PL:finT==='dds'?DDS:BAL;
 return `<div class="hd"><div><h2>Финансы · октябрь</h2><p>ОПиУ, ДДС и баланс собираются из операций портала. Финансист больше не скармливает выгрузки вручную — ассистент считает по живым данным.</p></div><div class="btns"><div class="seg">${[['pl','ОПиУ'],['dds','ДДС'],['bal','Баланс']].map(x=>`<a class="${finT===x[0]?'on':''}" onclick="finT='${x[0]}';render()">${x[1]}</a>`).join('')}</div><button class="bt" onclick="toast('Отчёт выгружен в Excel для главбуха.')">Excel</button></div></div>
 <div class="g21"><div class="tw"><table class="t"><thead><tr><th>Статья</th><th class="r">Сумма</th></tr></thead><tbody>${T.map(r=>`<tr><td>${r[0].startsWith('Итого')||r[0].startsWith('Остаток')?'<b>'+r[0]+'</b>':r[0]}</td><td class="r ${r[1]<0?'bad':''}">${tg(r[1])}</td></tr>`).join('')}${finT==='pl'?`<tr class="total"><td>Чистая прибыль</td><td class="r">${tg(tot)}</td></tr>`:''}</tbody></table></div>
 <div><div class="pan"><h3>По блокам</h3><div class="kv"><span>Астана, 8 станций</span><b>${tg(28900000)}</b></div><div class="kv"><span>Регионы, 10 своих</span><b>${tg(18500000)}</b></div><div class="kv"><span>Франшиза, 4 станции</span><b>${tg(2480000)}</b></div><div class="kv"><span>Рентабельность</span><b>${pct(tot,49880000)}%</b></div></div>
 ${said('«У нас есть отчёт ОПиУ, ДДС, баланс — это тоже по финансовой части».','','Маргулан')}</div></div>`};
/* ===== Платежи филиалов ===== */
let PAYS=[['R10','Роялти за октябрь',620000,'10.11','ожидается'],['R12','Роялти за октябрь',410000,'10.11','ожидается'],['R13','Аренда оборудования',810000,'10.11','ожидается'],['R14','Роялти за октябрь',380000,'12.11','ожидается'],['R10','Роялти за сентябрь',600000,'06.10','просрочен'],['R12','Роялти за сентябрь',395000,'08.10','оплачен']];
SC.pays=()=>`<div class="hd"><div><h2>Платежи филиалов</h2><p>Кто и сколько должен заплатить — по дням. Ассистент отвечает на вопрос «кто сегодня платит», финансист отмечает поступление.</p></div></div>
 <div class="strip"><div><small>Сегодня ждём</small><b>${tg(1840000)}</b><span>3 платежа</span></div><div><small>На неделе</small><b>${tg(2220000)}</b><span>4 платежа</span></div><div><small>Просрочено</small><b class="bad">${tg(600000)}</b><span>Атырау, 35 дней</span></div><div><small>Оплачено в октябре</small><b class="ok">${tg(2310000)}</b><span></span></div><div><small>Франчайзи</small><b>4</b><span>станции</span></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Филиал</th><th>Основание</th><th class="r">Сумма</th><th>Срок</th><th>Статус</th><th></th></tr></thead><tbody>${PAYS.map((p,i)=>`<tr><td><b>${esc(SID(p[0]).n)}</b></td><td>${p[1]}</td><td class="r">${tg(p[2])}</td><td>${p[3]}</td><td>${tag(p[4],p[4]==='оплачен'?'g':p[4]==='просрочен'?'r':'w')}</td><td>${p[4]!=='оплачен'?`<button class="bt sm" onclick="event.stopPropagation();PAYS[${i}][4]='оплачен';render();toast('Поступление отмечено, ДДС обновлён.')">Поступило</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;
/* ===== Маркетинг ===== */
SC.mkt=()=>{const tot=CH.reduce((a,c)=>a+c[1],0),leads=CH.reduce((a,c)=>a+c[2],0),rec=CH.reduce((a,c)=>a+c[3],0);
 return `<div class="hd"><div><h2>Маркетинг · октябрь</h2><p>Каналы, расходы, лиды, записи и пришедшие клиенты. Вопрос «сколько потратили на звонобот и сколько лидов пришло» — один клик или вопрос ассистенту.</p></div><div class="btns"><button class="bt" onclick="go('ai')">Спросить ассистента</button></div></div>
 <div class="strip"><div><small>Расход</small><b>${tg(tot)}</b><span>все каналы</span></div><div><small>Лиды</small><b>${fmt(leads)}</b><span>CPL ${tg(tot/leads)}</span></div><div><small>Записи на ТО</small><b class="ok">${fmt(rec)}</b><span>конверсия ${pct(rec,leads)}%</span></div><div><small>Цена записи</small><b>${tg(tot/rec)}</b><span></span></div><div><small>Повторные</small><b>604</b><span>самый дешёвый канал</span></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Канал</th><th class="r">Расход</th><th class="r">Лиды</th><th class="r">CPL</th><th class="r">Записи</th><th class="r">Конверсия</th><th style="width:18%"></th></tr></thead><tbody>${CH.map(c=>`<tr><td><b>${c[0]}</b></td><td class="r">${tg(c[1])}</td><td class="r">${fmt(c[2])}</td><td class="r">${c[1]?tg(c[1]/c[2]):'—'}</td><td class="r">${c[3]}</td><td class="r">${pct(c[3],c[2])}%</td><td>${bar(pct(c[3],c[2])*1.6,pct(c[3],c[2])>40?'g':'')}</td></tr>`).join('')}</tbody></table></div>
 <p style="font-size:11px;color:var(--muted);margin-top:8px">Пришлёте ТЗ маркетингового блока — соберём дашборд точно по нему.</p>`};
/* ===== Франшиза ===== */
SC.fr=()=>`<div class="hd"><div><h2>Франшиза</h2><p>Партнёрские станции работают в той же системе: свои права, свои отчёты, роялти считается автоматически от выручки.</p></div><div class="btns"><button class="bt p" onclick="toast('Анкета франчайзи отправлена кандидату.')">+ Кандидат во франчайзи</button></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Станция</th><th>Партнёр</th><th class="r">Выручка октябрь</th><th class="r">Роялти 8%</th><th>Стандарты</th><th>Платёж</th></tr></thead><tbody>${ST.filter(s=>s.fr).map((s,i)=>`<tr><td><b>${esc(s.n)}</b></td><td>${['ТОО «Каспий Авто»','ИП Кадырова','ТОО «Сыр Тех»','ИП Юн'][i]}</td><td class="r">${tg(s.rev*26)}</td><td class="r">${tg(s.rev*26*.08)}</td><td>${tag(['94%','88%','81%','92%'][i],i===2?'w':'g')}</td><td>${tag(i===0?'просрочен':'в срок',i===0?'r':'g')}</td></tr>`).join('')}</tbody></table></div>
 <div class="g2" style="margin-top:12px"><div class="pan"><h3>Воронка новых франчайзи</h3>${[['Заявки',14],['Встреча',6],['Расчёт окупаемости',3],['Договор',1]].map(r=>`<div class="kv"><span>${r[0]}</span><b>${r[1]}</b></div>`).join('')}</div>${said('«Индира, не забудьте газосмотр тоже надо добавить и франшизу».','','Маргулан')}</div>`;
/* ===== Газосмотр и доп. услуги ===== */
const SVC=[['Техосмотр легкового',4200,3820],['Газосмотр (ГБО)',6500,410],['Компьютерная диагностика',5000,380],['Проверка аккумулятора',1500,520],['Антифриз: проверка и долив',2000,290],['Тормозная жидкость',2500,240],['Пакет «Зима»: АКБ + антифриз + свет',4900,610]];
SC.svc=()=>`<div class="hd"><div><h2>Газосмотр и доп. услуги</h2><p>Прайс общий для всех станций, франчайзи видят его в своей системе. Продажа доп. услуг идёт в мотивацию оператора.</p></div></div>
 <div class="tw"><table class="t"><thead><tr><th>Услуга</th><th class="r">Цена</th><th class="r">Продано за октябрь</th><th class="r">Выручка</th></tr></thead><tbody>${SVC.map(s=>`<tr><td><b>${s[0]}</b></td><td class="r">${tg(s[1])}</td><td class="r">${fmt(s[2])}</td><td class="r">${tg(s[1]*s[2])}</td></tr>`).join('')}</tbody></table></div>
 ${said('«Проверили аккумулятор, компьютерную диагностику, антифриз или тормозную жидкость — это тоже услуги».','','Маргулан')}`;
/* ===== Блоки и права ===== */
const BL=[['HR','Индира','вакансии, онбординг, база знаний, досье, документы'],['Финансы и бухгалтерия','Айгерим','ОПиУ, ДДС, баланс, платежи, зарплата'],['Маркетинг','Дана','каналы, звонобот, бюджеты'],['Коммерческий','Ерлан','колл-центр, запись, напоминания, корпоративные продажи'],['Технический / производственный','Тимур','станции, оборудование, задачи'],['Филиалы и франшиза','начальники станций','своя станция: смены, машины, задачи']];
const PERM=['Пульт','Финансы','Зарплаты','HR и досье','Маркетинг','Колл-центр','Станции','Задачи'];
const PM={'Собственник':'11111111','HR-директор':'00110001','Финансовый директор':'11100011','Маркетолог':'00001101','РОП / колл-центр':'00000111','Технический директор':'00000011','Оператор станции':'00000001'};
SC.blocks=()=>`<div class="hd"><div><h2>Блоки и права директоров</h2><p>Оргструктура как у вас: у каждого блока директор и свои данные. Оператор видит только своё — свою смену, расчёт и базу знаний.</p></div></div>
 <div class="blg">${BL.map(b=>`<div class="pan"><code>${esc(b[1])}</code><h3>${esc(b[0])}</h3><p>${esc(b[2])}</p></div>`).join('')}</div>
 <div class="tw" style="margin-top:12px"><table class="t sm"><thead><tr><th>Роль</th>${PERM.map(p=>`<th>${p}</th>`).join('')}</tr></thead><tbody>${Object.entries(PM).map(([r,m])=>`<tr><td><b>${r}</b></td>${m.split('').map(x=>`<td>${x==='1'?tag('да','g'):'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
/* ===== 1С ===== */
SC.onec=()=>`<div class="hd"><div><h2>1С — по решению главбуха</h2><p>Первичка ведётся в портале. Два варианта — выбирает главный бухгалтер.</p></div></div>
 <div class="g2"><div class="pan"><code>вариант 1 · в пакете</code><h3>Выгрузка отчётов</h3><p style="font-size:11.6px;line-height:1.6">Портал выгружает реестры продаж, поступлений и зарплаты в Excel по шаблону главбуха. Бухгалтер загружает в 1С.</p></div>
 <div class="pan"><code>вариант 2 · 800 000 ₸</code><h3>Онлайн-обмен с 1С</h3><p style="font-size:11.6px;line-height:1.6">Документы уходят в 1С автоматически по OData: реализации, поступления, зарплата. Справочники синхронизируются. +1–2 недели к сроку.</p></div></div>
 ${said('«Это скажет главбух».','Решение по 1С — после разговора с главбухом.','Маргулан')}`;
/* ===== Битрикс ===== */
SC.bitrix=()=>`<div class="hd"><div><h2>Своя система vs Битрикс24 + ИИ-агенты</h2><p>Вам предложили Битрикс24 с агентами. Сравнение по тому, что важно сети из 22 станций.</p></div></div>
 <div class="tw"><table class="t"><thead><tr><th></th><th>Битрикс24 + доработки</th><th>Своя система Pllato</th></tr></thead><tbody>${[['Ежегодная плата','лицензия ≈ 1,5–2 млн ₸ в год, каждый год','0 ₸ — платите один раз'],['Доработки','по часам интегратора, в рамках возможностей коробки','в пакете до сдачи, дальше — по необходимости'],['Пользователи','тариф ограничивает число','без ограничений, сервер считает нагрузку'],['Под ваш процесс','подгоняете процесс под коробку','система описывает ваш процесс'],['Код и данные','принадлежат вендору','ваши: код, база, доступы'],['Смены, KPI, техосмотр, франшиза','отдельные приложения и интеграции','в одной системе'],['ИИ-агенты','внутри экосистемы вендора','MCP-сервер: любая модель, один ключ']].map(r=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td class="ok">${r[2]}</td></tr>`).join('')}</tbody></table></div>
 <div class="strip" style="margin-top:12px;grid-template-columns:repeat(3,1fr)"><div><small>Своя система</small><b>2,8 млн ₸</b><span>один раз</span></div><div><small>Битрикс за 2 года</small><b>3–4 млн ₸</b><span>лицензия, без доработок</span></div><div><small>Окупаемость</small><b class="ok">1–1,5 года</b><span>дальше — экономия каждый год</span></div></div>
 ${said('«В чём выгода именно вашего, с нуля разработанного? Напишите свои выгоды, чем отличаетесь от Битрикса».','','Маргулан')}`;
/* ===== Стоимость ===== */
let O1C=false,OAI=false;
SC.launch=()=>{const t=2800000+(O1C?800000:0);return `<div class="hd"><div><h2>Стоимость</h2><p>Стандартный пакет разработки. Абонентской платы нет — система ваша.</p></div></div>
 <div class="g21"><div class="pan price"><div class="kv"><span><b>Стандартный пакет</b><br><small>портал, 22 станции, колл-центр, запись и напоминания, операторы и смены, KPI и мотивация, задачник, HR и база знаний, ЭЦП, финансы, маркетинг, франшиза, пульт, базовый ИИ-ассистент (MCP, чат и голос, маршрутизация задач)</small></span><b>${tg(2800000)}</b></div>
  <label class="kv" style="cursor:pointer"><span><input type="checkbox" ${O1C?'checked':''} onchange="O1C=this.checked;render()"> Онлайн-обмен с 1С <small>(по решению главбуха)</small></span><b>${tg(800000)}</b></label>
  <label class="kv" style="cursor:pointer"><span><input type="checkbox" ${OAI?'checked':''} onchange="OAI=this.checked;render()"> Глубокие ИИ-сценарии по отделам</span><b>после ТЗ отделов</b></label>
  <div class="kv tot"><span>Итого</span><b>${tg(t)}</b></div>
  <div class="flow4" style="margin-top:12px"><div><b>1</b> 30% — старт, ${tg(t*.3)}</div><div><b>2</b> 40% — база на сервере, ${tg(t*.4)}</div><div><b>3</b> 30% — сдача и ключи, ${tg(t*.3)}</div><div><b>4</b> 3 месяца поддержки — бесплатно</div></div></div>
 <div><div class="pan"><h3>Сроки и условия</h3><div class="kv"><span>Срок</span><b>4–6 недель</b></div><div class="kv"><span>Пользователей</span><b>до 100 без доплат</b></div><div class="kv"><span>Сервер</span><b>PS.kz + копия в 2-м облаке</b></div><div class="kv"><span>После поддержки</span><b>$20 / час, по запросу</b></div><div class="kv"><span>Команда</span><b>~10 разработчиков, свой full-stack</b></div></div>
 ${said('«Оптимально посчитайте, сколько денег. Если нужно — без проблем заплатим. Компания растёт, мы тормозим».','','Маргулан')}</div></div>`};
/* ===== Каркас: верхние вкладки + левая колонка ===== */
function searchDemo(v){if(!v)return;const q=v.toLowerCase();const s=ST.find(x=>(x.n+x.city).toLowerCase().includes(q));if(s&&allowed('stations')){go('stations');stOpen(s.id);return}const c=CLI.find(x=>(x.n+x.car+x.ph).toLowerCase().includes(q));if(c&&allowed('remind')){go('remind');toast('Клиент: <b>'+esc(c.n)+'</b> · '+esc(c.car));return}toast('Не найдено. Попробуйте: «Сарыарка», «Камри», «Караганда».')}
function renderRoles(){const r=document.getElementById('roles');if(r)r.innerHTML=Object.entries(ROLES).map(([k,v])=>`<div class="role" onclick="enter('${esc(k)}')"><div class="rav">${esc(v.av)}</div><div><b>${esc(k)}</b><span>${esc(v.n)} · ${esc(v.note)}</span></div></div>`).join('');const s=document.getElementById('rsel');if(s)s.innerHTML=Object.keys(ROLES).map(k=>`<option>${esc(k)}</option>`).join('')}
const allowed=k=>ROLES[role].s.indexOf(k)>=0;
function enter(k){role=ROLES[k]?k:'Собственник';document.getElementById('gate').classList.add('hidden');document.getElementById('app').classList.remove('hidden');const s=document.getElementById('rsel');if(s)s.value=role;document.getElementById('me').textContent=ROLES[role].av;if(!allowed(cur))cur=ROLES[role].s[0];build()}
function switchRole(k){role=k;document.getElementById('me').textContent=ROLES[role].av;const s=document.getElementById('rsel');if(s)s.value=role;if(!allowed(cur))cur=ROLES[role].s[0];build();toast(`Роль <b>${esc(role)}</b>: ${esc(ROLES[role].note)}.`)}
function buildRail(){document.getElementById('rail').innerHTML=SEC.filter(s=>s.sub.some(x=>allowed(x[0]))).map(s=>`<a class="ri ${s.k===SECOF[cur]?'on':''}" onclick="go('${s.sub.filter(x=>allowed(x[0]))[0][0]}')"><span>${s.n}</span></a>`).join('');
 const S=SEC.find(x=>x.k===SECOF[cur]);document.getElementById('sub').innerHTML=`<h4>${esc(S.n)}</h4>`+S.sub.filter(x=>allowed(x[0])).map((x,i)=>`<a class="${x[0]===cur?'on':''}" onclick="go('${x[0]}')"><code>${String(i+1).padStart(2,'0')}</code>${esc(x[1])}</a>`).join('')+`<div class="shint"><b>${esc(role)}</b><br>${esc(ROLES[role].note)}</div>`}
function build(){buildRail();render()}
function render(){const f=SC[cur]||SC.dash;document.getElementById('ttl').textContent=SUBN[cur]||'ТехКонтроль';document.getElementById('content').innerHTML=`<div class="screen">${f()}</div>`;buildRail();try{history.replaceState(null,'','?s='+cur)}catch(e){}}
function go(k){if(!allowed(k)){toast('Этой роли раздел недоступен — так работают права. Переключите роль справа вверху.');return}cur=k;build();const c=document.querySelector('.content');if(c)c.scrollTop=0}
function openM(t,s,b){document.getElementById('mt').innerHTML=t;document.getElementById('ms').innerHTML=s;document.getElementById('mbody').innerHTML=b;document.getElementById('mbg').classList.add('show')}
function closeM(){document.getElementById('mbg').classList.remove('show')}
let tt=null;function toast(m){const t=document.getElementById('toast');t.innerHTML=m;t.classList.add('show');clearTimeout(tt);tt=setTimeout(()=>t.classList.remove('show'),6400)}
function xlsDay(){const h=`<html><head><meta charset="utf-8"></head><body><table border="1"><tr><th>Станция</th><th>Город</th><th>Машин сегодня</th><th>Выручка</th><th>Загрузка %</th></tr>${ST.map(r=>`<tr><td>${esc(r.n)}</td><td>${esc(r.city)}</td><td>${r.cars}</td><td>${r.rev}</td><td>${r.load}</td></tr>`).join('')}</table></body></html>`;try{const b=new Blob(['\ufeff'+h],{type:'application/vnd.ms-excel'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='Станции_'+TODAY+'.xls';document.body.appendChild(a);a.click();a.remove()}catch(e){}toast('Файл <b>Станции.xls</b> скачан.')}
let theme='light';function applyTheme(){document.body.classList.toggle('dark',theme==='dark')}function toggleTheme(){theme=theme==='dark'?'light':'dark';applyTheme()}
const TOUR=[['dash','1 · Пульт: 22 станции, машины, деньги, задачи — с телефона.'],['ai','2 · ИИ-ассистент: вопрос голосом → ответ из системы, задача → нужный отдел.'],['stations','3 · Станции и филиалы: загрузка, машины, выручка.'],['booking','4 · Запись на техосмотр по свободным окнам.'],['remind','5 · Напоминания об окончании ТО: бот → менеджер.'],['callc','6 · Колл-центр 24/7: входящие и пропущенные.'],['bot','7 · Звонобот: расходы и лиды.'],['shifts','8 · Смены операторов вместо Clockster.'],['kpi','9 · KPI и рейтинг операторов.'],['tasks','10 · Задачник вместо Trello: просрочки видит агент.'],['hr','11 · HR: отклики hh.ru внутри.'],['kb','12 · Онбординг и база знаний.'],['fin','13 · ОПиУ, ДДС, баланс.'],['mkt','14 · Маркетинг: каналы, CPL, конверсия.'],['bitrix','15 · Почему своя система, а не Битрикс24.'],['launch','16 · 2,8 млн ₸, 4–6 недель, без подписок.']];
let ti=-1,tRun=false;function tour(){if(tRun){tRun=false;return}tRun=true;ti=-1;step()}
function step(){if(!tRun)return;ti++;if(ti>=TOUR.length){tRun=false;toast('Сценарий закончен — всё кликается.');return}const [k,m]=TOUR[ti];if(!allowed(k))switchRole('Собственник');cur=k;build();toast('<b>'+m+'</b>');setTimeout(step,5200)}
(function(){renderRoles();applyTheme();const s=document.getElementById('rsel');if(s)s.addEventListener('change',e=>switchRole(e.target.value));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeM();tRun=false}});
 let q='';try{q=new URLSearchParams(location.search).get('s')||''}catch(e){}
 if(q&&SECOF[q]){const r=Object.keys(ROLES).find(k=>ROLES[k].s.indexOf(q)>=0);if(r){cur=q;enter(r)}}})();
function stopTour(){tRun=false}
